// ERPNext (illumenate_lighting qbo_client.py) signs the raw body:
//   X-QBO-Signature = hex(HMAC-SHA256(body, QBO_WEBHOOK_SECRET))
// Body: {"method": "GET"|"POST", "path": "/invoice", "params": {...}, "body": {...}, "ts": <unix seconds>}
const crypto = require('crypto');

const QBO_WEBHOOK_SECRET = ''; // fallback only; prefer the n8n Variable QBO_WEBHOOK_SECRET (same as ilL-QBO-Settings)
const QBO_REALM_ID = '';       // fallback only; prefer the n8n Variable QBO_REALM_ID (QuickBooks Company ID)
const QBO_API_BASE = 'https://quickbooks.api.intuit.com'; // sandbox company: https://sandbox-quickbooks.api.intuit.com
function setting(name, fallback) {
  // n8n Variables win; the constant above is the fallback for plans without Variables.
  try { const v = $vars[name]; if (v) return String(v); } catch (e) {}
  return fallback;
}

const MAX_SKEW_SECONDS = 300;
const ALLOWED_PATH = /^\/(query|customer|invoice|creditmemo|payment|item|account)(\/[0-9]+)?$/;
const ALLOWED_PARAMS = ['query', 'requestid', 'operation', 'include'];
const reject = (status, error) => [{ json: { ok: false, status, error } }];

const secret = setting('QBO_WEBHOOK_SECRET', QBO_WEBHOOK_SECRET);
const realm = setting('QBO_REALM_ID', QBO_REALM_ID);
const base = setting('QBO_API_BASE', QBO_API_BASE).replace(/\/+$/, '');
if (!secret) return reject(500, 'QBO_WEBHOOK_SECRET is not configured in n8n');
if (!realm) return reject(500, 'QBO_REALM_ID is not configured in n8n');

const item = $input.first();
let raw;
if (item.binary && item.binary.data) {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} else {
  raw = Buffer.from(JSON.stringify(item.json.body ?? {}), 'utf8');
}

const headers = item.json.headers || {};
const provided = String(headers['x-qbo-signature'] || '').toLowerCase().replace(/^sha256=/, '');
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
const a = Buffer.from(provided);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return reject(401, 'bad signature: QBO_WEBHOOK_SECRET in n8n differs from ilL-QBO-Settings');
}

let req;
try { req = JSON.parse(raw.toString('utf8')); } catch (e) { return reject(400, 'body is not JSON'); }
if (Math.abs(Date.now() / 1000 - Number(req.ts || 0)) > MAX_SKEW_SECONDS) return reject(401, 'stale request (clock skew or replay)');
if (!['GET', 'POST'].includes(req.method)) return reject(400, `method ${req.method} not allowed`);
if (!ALLOWED_PATH.test(String(req.path || ''))) return reject(403, `path ${req.path} not allowed`);

const qs = new URLSearchParams({ minorversion: '75' });
for (const key of ALLOWED_PARAMS) {
  const value = req.params && req.params[key];
  if (value !== undefined && value !== null && value !== '') qs.set(key, String(value));
}
return [{
  json: {
    ok: true,
    method: req.method,
    // Intuit expects %20, not '+', for spaces in the query string.
    url: `${base}/v3/company/${encodeURIComponent(realm)}${req.path}?${qs.toString().replace(/\+/g, '%20')}`,
    body: req.body || {},
  },
}];

// Normalize QuickBooks' answer for ERPNext: {ok, status, body, intuit_tid} or {ok:false, status, error}.
return $input.all().map((item) => {
  const r = item.json || {};
  if (r.statusCode === undefined) {
    const err = r.error && (r.error.message || r.error.description) || r.error || 'request to QuickBooks failed';
    return { json: { ok: false, status: 502, error: String(err) } };
  }
  const status = Number(r.statusCode);
  const headers = r.headers || {};
  return {
    json: {
      ok: status >= 200 && status < 300,
      status,
      body: r.body === undefined ? null : r.body,
      intuit_tid: headers.intuit_tid || headers['intuit-tid'] || null,
    },
  };
});
